-- RC50.83 - Central Executiva 360 e Sala de Situação Municipal. Idempotente, sem dados simulados.
do $$ begin
 if to_regclass('sigov.tenant') is null then raise exception 'Schema obrigatório ausente: sigov.tenant'; end if;
 if to_regclass('sigov.entidade') is null then raise exception 'Schema obrigatório ausente: sigov.entidade'; end if;
end $$;

do $$ declare t text; begin
 foreach t in array array['executivo_painel','executivo_widget','executivo_indicador','executivo_meta','executivo_meta_marco','executivo_meta_vinculo_modulo','executivo_pendencia','executivo_alerta','executivo_encaminhamento','executivo_aprovacao','executivo_decisao','executivo_briefing','executivo_briefing_item','executivo_sala_situacao','executivo_sala_situacao_item','executivo_relatorio_execucao'] loop
  execute format('create table if not exists sigov.%I (
   id bigint generated by default as identity primary key,
   tenant_id bigint not null, entidade_id bigint not null, titulo varchar(240) not null,
   modulo varchar(80), tipo varchar(40) not null default ''GERAL'', status varchar(32) not null default ''ATIVO'',
   severidade varchar(10), prioridade varchar(10), percentual numeric(5,2), valor numeric(18,2), orcamento numeric(18,2),
   prazo date, responsavel_id bigint, responsavel_nome varchar(200), unidade_id bigint,
   origem_tipo varchar(80), origem_id bigint, regra_origem varchar(240), descricao text, justificativa text, resultado text,
   visibilidade varchar(20) not null default ''INTERNA'', documento_id bigint, dados jsonb not null default ''{}''::jsonb,
   ciente_at timestamptz, ciente_by bigint, decidido_at timestamptz, decidido_by bigint,
   created_at timestamptz not null default now(), updated_at timestamptz not null default now(), created_by bigint, updated_by bigint,
   constraint ck_%s_percentual check(percentual is null or percentual between 0 and 100),
   constraint ck_%s_valores check((valor is null or valor>=0) and (orcamento is null or orcamento>=0)),
   constraint ck_%s_severidade check(severidade is null or severidade in (''BAIXA'',''MEDIA'',''ALTA'',''CRITICA'')),
   constraint ck_%s_prioridade check(prioridade is null or prioridade in (''BAIXA'',''MEDIA'',''ALTA'',''CRITICA'')),
   constraint ck_%s_visibilidade check(visibilidade in (''INTERNA'',''RESTRITA'',''PUBLICA'')),
   constraint ck_%s_prazo check(prazo is null or prazo>=date ''1900-01-01''),
   constraint ck_%s_tipo check(length(trim(tipo)) between 2 and 40),
   constraint ck_%s_status check(status in (''ATIVO'',''INATIVO'',''ABERTA'',''EM_MONITORAMENTO'',''RESOLVIDA'',''CANCELADA'',''EM_DIA'',''ATRASADA'',''CRITICA'',''REPROGRAMADA'',''PENDENTE'',''APROVADA'',''REJEITADA'',''CONCLUIDO'',''LIDO'',''ENCAMINHADO'',''SILENCIADO''))
  )',t,t,t,t,t,t,t,t,t);
  execute format('create index if not exists ix_%s_contexto on sigov.%I(tenant_id,entidade_id,status,updated_at desc)',t,t);
  execute format('create index if not exists ix_%s_modulo on sigov.%I(tenant_id,entidade_id,modulo,status)',t,t);
  execute format('create index if not exists ix_%s_prioridade on sigov.%I(tenant_id,entidade_id,prioridade,prazo)',t,t);
  execute format('create index if not exists ix_%s_responsavel on sigov.%I(tenant_id,entidade_id,responsavel_id,status)',t,t);
 end loop;
end $$;

-- Regras de domínio não destrutivas para transições críticas.
do $$ begin
 if not exists(select 1 from pg_constraint where conname='ck_executivo_sala_encerramento') then alter table sigov.executivo_sala_situacao add constraint ck_executivo_sala_encerramento check(status not in ('RESOLVIDA','CANCELADA') or length(trim(coalesce(resultado,'')))>=10); end if;
 if not exists(select 1 from pg_constraint where conname='ck_executivo_pendencia_encerramento') then alter table sigov.executivo_pendencia add constraint ck_executivo_pendencia_encerramento check(status not in ('RESOLVIDA','CANCELADA') or length(trim(coalesce(resultado,'')))>=10); end if;
 if not exists(select 1 from pg_constraint where conname='ck_executivo_meta_justificativa') then alter table sigov.executivo_meta add constraint ck_executivo_meta_justificativa check(status not in ('ATRASADA','CANCELADA','REPROGRAMADA') or length(trim(coalesce(justificativa,'')))>=10); end if;
 if not exists(select 1 from pg_constraint where conname='ck_executivo_alerta_origem') then alter table sigov.executivo_alerta add constraint ck_executivo_alerta_origem check(regra_origem is not null and origem_tipo is not null); end if;
end $$;

insert into sigov.permissao(chave,descricao,modulo,ativo,created_at)
select chave,nome,'executivo',true,now() from(values
 ('EXECUTIVO_DASHBOARD_VIEW','Executivo: visualizar dashboard'),('EXECUTIVO_SALA_VIEW','Executivo: visualizar sala'),('EXECUTIVO_SALA_MANAGE','Executivo: gerenciar sala'),('EXECUTIVO_META_VIEW','Executivo: visualizar metas'),('EXECUTIVO_META_MANAGE','Executivo: gerenciar metas'),('EXECUTIVO_PENDENCIA_VIEW','Executivo: visualizar pendências'),('EXECUTIVO_PENDENCIA_MANAGE','Executivo: gerenciar pendências'),('EXECUTIVO_ALERTA_VIEW','Executivo: visualizar alertas'),('EXECUTIVO_ALERTA_MANAGE','Executivo: gerenciar alertas'),('EXECUTIVO_APROVACAO_VIEW','Executivo: visualizar aprovações'),('EXECUTIVO_APROVACAO_MANAGE','Executivo: gerenciar aprovações'),('EXECUTIVO_DECISAO_VIEW','Executivo: visualizar decisões'),('EXECUTIVO_DECISAO_MANAGE','Executivo: gerenciar decisões'),('EXECUTIVO_BRIEFING_VIEW','Executivo: visualizar briefing'),('EXECUTIVO_RELATORIO_EXPORT','Executivo: exportar relatórios')) p(chave,nome)
on conflict(chave) do update set descricao=excluded.descricao,modulo=excluded.modulo,ativo=true;
